const fs = require('fs');
const ENV = (n) => (typeof $env !== 'undefined' && $env[n]) || '';
const STATE = '/home/node/.n8n/state';
const DRAFTS = STATE + '/drafts';
const LOG = '/home/node/.n8n/logs';
// Pangram warn-path audit notes (issue #76) ride the same
// moderation.jsonl the sibling nodes append to. Best-effort like
// their log(): the mkdir AND the append stay swallowed - a broken
// logs dir must never refuse a draft on this public webhook (delib-
// erately NOT part of mkdirErrs: warn-path failures never gate).
try { fs.mkdirSync(LOG, { recursive: true }); } catch (e) {}
const log = (rec) => {
  try {
    fs.appendFileSync(LOG + '/moderation.jsonl',
      JSON.stringify({ ts: new Date().toISOString(), ...rec }) + '\n');
  } catch (e) {}
};
// an unguarded mkdirSync throw here killed the node before the item
// loop could answer - the moderation-draft caller saw a bare
// execution failure with no draft-level reason. Collect it like the
// mkdirErrs preludes in Handle TG Update / Generate Drafts /
// sp-tg-setup and let the loop refuse each item with the
// {kind:'msg', ok:false} shape every other refusal uses (after the
// secret gate below - the state dir's health is config state like
// chat_id).
// SYNC-BEGIN: mkdir-collect
const mkdirErrs = [];
for (const d of [DRAFTS]) {
  try {
    fs.mkdirSync(d, { recursive: true });
  } catch (e) {
    mkdirErrs.push({ dir: d,
      error: String((e && e.message) || e).slice(0, 150) });
  }
}
// SYNC-END: mkdir-collect
// SYNC-BEGIN: media-resolve
const MEDIA_ROOT = '/home/node/materials';
const MEDIA_ROOT_REAL = (() => {
  try { return fs.realpathSync(MEDIA_ROOT); } catch (e) { return MEDIA_ROOT; }
})();
// moderation-draft is a public webhook, so media[] must never resolve
// outside the read-only materials/ mount: a bare absolute host path
// (/etc/..., a DB file) or a symlink inside materials/ pointing out
// would otherwise be read and sent back over Telegram
const underRoot = (p) => {
  try {
    const rp = fs.realpathSync(p);
    return rp === MEDIA_ROOT_REAL || rp.startsWith(MEDIA_ROOT_REAL + '/');
  } catch (e) { return false; }
};
// media paths may arrive as host paths, materials/... relatives or
// bare filenames - resolve them against the read-only mount.
const resolveMedia = (s) => {
  const p = String(s || '');
  if (!p) return null;
  const cands = [];
  const m = p.match(/(?:^|\/)materials\/(.+)$/);
  if (m) cands.push(MEDIA_ROOT + '/' + m[1]);
  if (p.startsWith('/')) cands.push(p);
  const base = p.split('/').pop();
  cands.push(MEDIA_ROOT + '/photos/' + base, MEDIA_ROOT + '/' + base);
  for (const c of cands) {
    if (fs.existsSync(c) && underRoot(c)) return c;
  }
  return null;
};
const mimeOf = (p) => (/\.png$/i.test(p) ? 'image/png'
  : /\.webp$/i.test(p) ? 'image/webp' : 'image/jpeg');
// SYNC-END: media-resolve

// operator chat_id is pinned config: TELEGRAM_CHAT_ID env first, the
// tg.json written by sp-tg-setup as compat fallback. It is never taken
// from incoming webhook payloads.
let chatId = ENV('TELEGRAM_CHAT_ID') || null;
if (!chatId) {
  try { chatId = JSON.parse(fs.readFileSync(STATE + '/tg.json', 'utf8')).chat_id; } catch (e) {}
}
// a missing chat_id is reported per-item AFTER the secret check below:
// answering 'chat_id unknown' to an unauthenticated caller on this
// public endpoint would leak server config state

// atomic draft writes: tmp + rename - a crash mid-writeFileSync would
// leave a torn JSON, and the overwrite guard below must fail CLOSED on
// an unreadable file (it does), so never produce one here.
// SYNC: sibling copies live in Handle TG Update and Compose Message
// (this workflow), Publish Tick (sp-publish, hardened 0o600 variant),
// Generate Drafts (sp-content-gen) and Resolve Chat + Webhook
// (sp-tg-setup). n8n Code nodes cannot share a prelude - replicate
// any fix to every copy by hand.
// SYNC-BEGIN: write-json-atomic
const writeJsonAtomic = (p, obj) => {
  const tmp = p + '.tmp-' + Date.now().toString(36) +
    Math.random().toString(36).slice(2, 6);
  fs.writeFileSync(tmp, JSON.stringify(obj, null, 2));
  fs.renameSync(tmp, p);
};
// SYNC-END: write-json-atomic

// Re-read-then-mutate draft writes - the same pattern Handle TG
// Update's updateDraft follows for every callback save: the
// rewrite-expiry seal below must not stamp the earlier-read snapshot
// back over a concurrent write, so guard(cur) vetoes the write when
// the file moved on underneath us. Read/write errors propagate - the
// caller treats a throw as 'state save failed'.
// SYNC-BEGIN: update-draft
const updateDraft = (id, mutate, guard) => {
  const cur = JSON.parse(
    fs.readFileSync(DRAFTS + '/' + id + '.json', 'utf8'));
  if (guard && !guard(cur)) return null;
  mutate(cur);
  validateDraftShape(cur);
  writeJsonAtomic(DRAFTS + '/' + id + '.json', cur);
  return cur;
};
// SYNC-END: update-draft
// Light draft-file shape gate (issue #69): runs inside updateDraft
// and before every direct DRAFTS/<id>.json write, so a malformed
// object throws BEFORE writeJsonAtomic's tmp+rename - corrupt state
// never lands in state/drafts/. Shape only: the four fields every
// reader dereferences (id, platform, status, created_at), not a
// full schema. The platform enum lists the canonical writer keys
// (content-gen pins drafts to its MAP keys: linkedin/fb/vk/habr)
// plus 'facebook' (the documented PUBLISH_PLATFORMS spelling,
// canonPlat-mapped at read) and 'unknown' (Prepare Draft's own
// default when the producer sent none). The status enum lists every
// value this workflow persists into a draft file.
// SYNC-BEGIN: draft-shape
const DRAFT_PLATFORMS = { linkedin: true, facebook: true, fb: true,
  vk: true, habr: true, unknown: true };
const DRAFT_STATUSES = { delivering: true, 'deliver-failed': true,
  pending: true, approved: true, rejected: true, rewrite: true,
  'rewrite-expired': true };
const validateDraftShape = (d) => {
  const bad = (why) => {
    throw new Error('malformed draft write refused: ' + why);
  };
  if (!d || typeof d !== 'object') bad('not an object');
  if (typeof d.id !== 'string' || !d.id) bad('id not a string');
  if (!DRAFT_PLATFORMS[String(d.platform)]) {
    bad('platform ' + JSON.stringify(d.platform) +
      ' not in ' + Object.keys(DRAFT_PLATFORMS).join('/'));
  }
  if (!DRAFT_STATUSES[String(d.status)]) {
    bad('status ' + JSON.stringify(d.status) +
      ' not in ' + Object.keys(DRAFT_STATUSES).join('/'));
  }
  if (!Number.isFinite(Date.parse(d && d.created_at))) {
    bad('created_at missing or unparseable');
  }
};
// SYNC-END: draft-shape

// issue #70: the draft-file transactions below (entry read, rewrite
// seal, REWRITABLE/moved guards, writeJsonAtomic stamp) race operator
// callbacks in Handle TG Update under parallel executions - a
// moderate press landing between the entry read and the stamp would
// be clobbered back to 'delivering' while its side effects (the
// Approve's queue file) still run. withLock serializes them under a
// tokened state/locks/<key>.lock file: EEXIST = live lock = a thrown
// LockBusyError (.lockBusy = true) the caller converts to the same
// in-band {kind:'msg', ok:false} refusal every other guard uses;
// an expired or unreadable lock is stolen via tmp+rename and proven
// by re-read; release re-reads and unlinks only our own token.
// SYNC: identical copies live in Handle TG Update (this workflow)
// and Publish Tick (sp-publish). n8n Code nodes cannot share a
// prelude - replicate any fix to every copy by hand.
// SYNC-BEGIN: file-lock
const LOCKS_DIR = STATE + '/locks';
try { fs.mkdirSync(LOCKS_DIR, { recursive: true }); } catch (e) {}
const lockBusyError = () => {
  const e = new Error('state lock busy');
  e.name = 'LockBusyError';
  e.lockBusy = true;
  return e;
};
const withLock = (key, ttlMs, fn) => {
  const lp = LOCKS_DIR + '/' + key + '.lock';
  // no crypto/process in Code nodes - timestamp+random like the
  // writeJsonAtomic tmp names is entropy enough for a lock token
  const mine = Date.now().toString(36) + '-' +
    Math.random().toString(36).slice(2, 10);
  const claim = JSON.stringify({ token: mine, exp: Date.now() + ttlMs });
  let held = false;
  try {
    fs.writeFileSync(lp, claim, { flag: 'wx', mode: 0o600 });
    held = true;
  } catch (e) {
    if (!e || e.code !== 'EEXIST') throw e;
    // only a PROVEN-live lock (readable, exp in the future) makes us
    // busy - anything else is stolen, then verified by re-read
    // because a competing stealer may have won the rename
    let cur = null;
    try { cur = JSON.parse(fs.readFileSync(lp, 'utf8')); } catch (e2) {}
    if (cur && Number.isFinite(Number(cur.exp)) &&
        Date.now() <= Number(cur.exp)) {
      throw lockBusyError();
    }
    const tmp = lp + '.tmp-' + mine;
    try {
      fs.writeFileSync(tmp, claim, { mode: 0o600 });
      fs.renameSync(tmp, lp);
      held = JSON.parse(fs.readFileSync(lp, 'utf8')).token === mine;
    } catch (e3) { held = false; }
    try { fs.unlinkSync(tmp); } catch (e4) {}
    if (!held) throw lockBusyError();
  }
  try {
    return fn();
  } finally {
    if (held) {
      try {
        const cur = JSON.parse(fs.readFileSync(lp, 'utf8'));
        if (cur && cur.token === mine) fs.unlinkSync(lp);
      } catch (e5) {
        // release failures never propagate: a leaked lock expires
        // on its own; ENOENT just means it was already removed
        if (!e5 || e5.code !== 'ENOENT') {
          try {
            if (typeof log === 'function') {
              log({ action: 'lock-release-failed', key: key,
                error: String(e5).slice(0, 120) });
            }
          } catch (e6) {}
        }
      }
    }
  }
};
// SYNC-END: file-lock

// Pangram AI-check warn-gate (issue #76): shared prelude for the two
// readers in this workflow - Prepare Draft (fresh-check enqueue at
// card prep) and Handle Pangram Results (result replies, credit
// re-sync, the one text-hash re-check). WARN-mode ONLY: PANGRAM_GATE
// 'warn' (default) enqueues pangram_check tasks into the hands-queue
// and replies on the moderation card; 'off' disables the whole path.
// Nothing in the pangram path may ever gate or block moderation -
// every failure degrades to a draft-field stamp and/or a
// moderation.jsonl note.
// SYNC: identical copy lives in Handle Pangram Results (this
// workflow) - n8n Code nodes cannot share a prelude, so replicate
// any fix to both copies by hand.
// SYNC-BEGIN: pangram-gate
// exact-token gate: only the literal 'warn' enables the path. 'off'
// disables it quietly; 'block' is a RESERVED future mode and every
// other value (typos included) fails CLOSED to 'disabled' - a
// misspelled 'wran' must never silently behave like 'warn'. The
// ledger note records the rejected value once per execution.
const PANGRAM_GATE_RAW =
  String(ENV('PANGRAM_GATE') || 'warn').trim().toLowerCase();
const PANGRAM_GATE = (PANGRAM_GATE_RAW === 'warn' ||
  PANGRAM_GATE_RAW === 'off') ? PANGRAM_GATE_RAW : 'disabled';
if (PANGRAM_GATE === 'disabled') {
  try {
    log({ action: 'ai-check-gate-disabled',
      value: PANGRAM_GATE_RAW.slice(0, 40) });
  } catch (e) {}
}
// free Pangram web-checker credits price at 1 per 100 words, so the
// cost estimate is ceil(words/100). PANGRAM_DAILY_CREDITS overrides
// the daily spend ceiling, default 20 - an explicit '0' means ZERO
// (empty/unset or non-numeric falls back to 20; a '|| 20' fallback
// would wrongly turn a real 0 into the default). est_spent is
// charged OPTIMISTICALLY at enqueue (before the recipe runs); Handle
// Pangram Results re-syncs last_seen_left from the recipe's own
// 'N left' header read-back when the result lands.
const PANGRAM_DAILY = (() => {
  const raw = String(ENV('PANGRAM_DAILY_CREDITS') || '').trim();
  if (!raw) return 20;
  const n = Number.parseInt(raw, 10);
  return Number.isFinite(n) ? Math.max(0, n) : 20;
})();
const PANGRAM_CREDITS = STATE + '/pangram_credits.json';
// Pangram's own reliability floor: texts under ~150 words produce an
// inconclusive verdict - stamping inconclusive instead of enqueueing
// burns no credit.
const PANGRAM_MIN_WORDS = 150;
// hands-agent task queue (the host's hands-agent/queue bind mount,
// same root the habr driver enqueues into)
const HANDS_QUEUE = '/home/node/hands-queue';
// word count = whitespace-split count: the simplest honest proxy for
// both the reliability floor and the credit pricing above. Markup,
// URLs and punctuation clusters all count as 'words'.
const pangramWords = (text) =>
  String(text || '').split(/\s+/).filter(Boolean).length;
// FNV-1a over the draft text - the same non-crypto hash family the
// preview_v tokens use (Code nodes only require fs). text_fnv pins an
// ai_check record to the exact text it was computed on, so a later
// edit is detectable by hash rather than by re-reading the body.
const pangramFnv = (s) => {
  let h = 0x811c9dc5;
  s = String(s || '');
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619) >>> 0;
  }
  return h.toString(36);
};
const pangramToday = () => new Date().toISOString().slice(0, 10);
// counter state {date, est_spent, last_seen_left, charged}: est_spent
// resets on date change (a daily window matching the credit replenish
// cycle); last_seen_left moves only when a recipe result reports the
// real 'N left' header figure. charged[] is the humanizer eval's
// per-day charge-dedupe ledger (issue #78): it MUST reset with the
// date because whichever reader rolls the counter first after
// midnight decides for both - a stale charged[tid] would let the
// eval's same-tid re-arm enqueue a real task uncharged
const pangramLoadCredits = () => {
  let c = null;
  try {
    c = JSON.parse(fs.readFileSync(PANGRAM_CREDITS, 'utf8'));
  } catch (e) {}
  if (!c || typeof c !== 'object') c = {};
  if (c.date !== pangramToday()) {
    c.date = pangramToday();
    c.est_spent = 0;
    // the per-day charge-dedupe ledger resets with the daily counter -
    // entries are only valid for same-day idempotent re-arms
    c.charged = {};
  }
  c.est_spent = Number(c.est_spent) || 0;
  if (!Number.isFinite(Number(c.last_seen_left))) {
    c.last_seen_left = null;
  }
  return c;
};
// SYNC-END: pangram-gate

// moderation-draft is reachable through the public edge proxy, so
// draft CREATION needs its own shared-secret gate - the
// TG_WEBHOOK_SECRET check on tg-moderation only covers Telegram
// deliveries, and the draft_id allowlist + overwrite guard below only
// protect EXISTING drafts. Without this, anyone who knows the URL can
// push unlimited previews with live Approve buttons into the operator
// chat (one tap = a wall.post on the real VK wall). Callers must send
// X-Shared-Token or X-TG-Draft-Secret matching DRAFT_WEBHOOK_SECRET
// (content-gen is the internal caller and sends it). Fail closed when
// the env is unset - a dead endpoint beats a public spam surface.
// Constant-time-ish compare without crypto (only fs is allowed in
// Code nodes).
// SYNC: identical padded compares live in Handle TG Update's
// secretOk (this workflow, TG_WEBHOOK_SECRET gate) and Generate
// Drafts' cgSecretOk (sp-content-gen, CONTENT_GEN_WEBHOOK_SECRET
// gate) - n8n Code nodes cannot share a prelude, so replicate any
// fix to all three copies.
const DRAFT_SECRET = ENV('DRAFT_WEBHOOK_SECRET');
// SYNC-BEGIN: padded-compare
const secretOk = (got) => {
  const a = String(got == null ? '' : got);
  if (!DRAFT_SECRET) return false;
  // no early return on a length mismatch: it leaks the expected
  // secret length through response timing on this public endpoint.
  // Pad both operands to a shared length and fold the length delta
  // into diff so a padded tail can never compare equal. The first
  // loop count is a FIXED 64 - a bound of SECRET.length would make
  // the compare cost proportional to the secret's length, the very
  // leak the floor exists to hide, and a.length stays OUT of every
  // bound so an over-long attacker header cannot stretch the compare
  // either. Positions past 64 are NOT ignored: the second loop folds
  // the tail for i < SECRET.length (a per-deployment constant), so a
  // >64 configured secret compares in full instead of degrading to a
  // prefix-only check. padEnd never truncates, and charCodeAt past
  // the end of pa yields NaN (folds as 0 ^ pb char - still a nonzero
  // diff); the length-xor above rejects whatever length mismatch is
  // left.
  const len = 64;
  const pa = a.padEnd(len, '\0');
  const pb = DRAFT_SECRET.padEnd(len, '\0');
  let diff = a.length ^ DRAFT_SECRET.length;
  for (let i = 0; i < len; i++) {
    diff |= pa.charCodeAt(i) ^ pb.charCodeAt(i);
  }
  for (let i = len; i < DRAFT_SECRET.length; i++) {
    diff |= pa.charCodeAt(i) ^ pb.charCodeAt(i);
  }
  return diff === 0;
};
// SYNC-END: padded-compare

const out = [];
for (const item of $input.all()) {
  // the webhook node passes request headers through on
  // item.json.headers (lowercased names). Reject before any draft
  // write or Telegram send - the whole body is untrusted until the
  // secret check passes. The msg-kind item below short-circuits
  // Compose Message, so a rejected call answers {ok:false} and nothing
  // reaches the operator chat.
  const hdrs = (item.json && item.json.headers) || {};
  if (!secretOk(hdrs['x-shared-token']) &&
      !secretOk(hdrs['x-tg-draft-secret'])) {
    out.push({ json: { kind: 'msg', ok: false,
      error: DRAFT_SECRET
        ? 'unauthorized - missing/invalid draft webhook secret'
        : 'unauthorized - DRAFT_WEBHOOK_SECRET not configured (fails closed)' } });
    continue;
  }
  // config checks come after the secret gate - see the chatId note above
  if (!chatId) {
    out.push({ json: { kind: 'msg', ok: false,
      error: 'chat_id unknown - set TELEGRAM_CHAT_ID or run workflow sp-tg-setup' } });
    continue;
  }
  if (mkdirErrs.length) {
    out.push({ json: { kind: 'msg', ok: false,
      error: 'draft store unavailable - mkdir ' + DRAFTS +
        ' failed: ' + mkdirErrs[0].error } });
    continue;
  }
  const b = item.json.body || item.json;
  // draft_id is caller-controlled on the public moderation-draft
  // webhook and lands in file paths below (draft file, TG captions,
  // queue file on Approve) - allowlist it, reject everything else:
  // a '../' would escape the drafts dir for arbitrary-path writes
  const rawId = b.draft_id;
  // a SUPPLIED draft_id must be a non-empty string: a falsy caller
  // value (0, false) slips through String(rawId) into a generated id
  // and a non-string gets coerced, so the delivered draft_id would
  // silently differ from the id the caller asked for and tracks.
  // undefined/null still means 'generate one here'.
  if (rawId !== undefined && rawId !== null &&
      (typeof rawId !== 'string' || rawId === '')) {
    out.push({ json: { kind: 'msg', ok: false,
      error: 'invalid draft_id: non-empty string expected' } });
    continue;
  }
  if (rawId !== undefined && rawId !== null &&
      !/^[A-Za-z0-9_-]+$/.test(String(rawId))) {
    out.push({ json: { kind: 'msg', ok: false,
      error: 'invalid draft_id: [A-Za-z0-9_-] only' } });
    continue;
  }
  // the id rides inside Telegram callback_data ('ap:<id>:<ver>') -
  // 64 bytes hard cap minus ~4 bytes of action prefix and ~14 bytes
  // of version token leaves ~46, capped at 40 with margin. A longer
  // id would make Telegram reject the preview's keyboard and wedge
  // the draft in 'deliver-failed' with a far less readable error
  if (rawId !== undefined && rawId !== null &&
      String(rawId).length > 40) {
    out.push({ json: { kind: 'msg', ok: false,
      error: 'invalid draft_id: 40 chars max (callback_data budget)' } });
    continue;
  }
  const id = String(rawId || 'd' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6));
  const warnings = Array.isArray(b.warnings) ? b.warnings.map(String)
    : (b.warnings ? [String(b.warnings)] : []);
  const draft = {
    id: id,
    platform: b.platform || 'unknown',
    topic: b.topic || '',
    text: String(b.text || ''),
    // String() like the sibling fields: a non-string truthy image
    // (object/array) would otherwise land verbatim in the draft file
    // and the queue payload
    image: String(b.image || b.image_path || ''),
    media: Array.isArray(b.media) ? b.media.map(String)
      : (b.media ? [String(b.media)] : []),
    caption_note: String(b.caption_note || ''),
    scope: String(b.scope || ''),
    // canonical post_id (issue #12): minted by content-gen at fan-out
    // and forwarded through the moderation-draft body. Allowlisted
    // charset only - the value lands in the TG preview header
    // (Compose Message) and the publish queue payload. '' when the
    // caller supplied none or an invalid one: pre-registry callers
    // (manual drafts, older producers) simply carry no grouping id.
    post_id: /^[A-Za-z0-9_-]{1,64}$/.test(String(b.post_id || ''))
      ? String(b.post_id) : '',
    test: b.test === true,
    warnings: warnings,
    // habr-only fields (docs/habr-driver-spec.md): writer-habr emits
    // kind/title/hubs/tags alongside text through this body. Stamped
    // only when supplied so non-habr draft files stay byte-identical;
    // the queue payload snapshots them from `d` at Approve and the
    // habr driver enforces the content contract on them.
    ...(b.kind !== undefined ? { kind: String(b.kind || '') } : {}),
    ...(b.title !== undefined ? { title: String(b.title || '') } : {}),
    ...(b.hubs !== undefined
      ? { hubs: (Array.isArray(b.hubs) ? b.hubs : [b.hubs])
          .map(String).filter(Boolean) } : {}),
    ...(b.tags !== undefined
      ? { tags: (Array.isArray(b.tags) ? b.tags : [b.tags])
          .map(String).filter(Boolean) } : {}),
    ...(b.text_md !== undefined
      ? { text_md: String(b.text_md || '') } : {}),
    // 'delivering', NOT 'pending': the preview sendMessage in Compose
    // Message has not run yet, and 'pending' is only persisted after
    // tg_ok is confirmed there. A file born 'pending' wedged the
    // draft_id behind the overwrite guard below whenever delivery
    // failed - 'pending' is non-rewritable and no Approve button ever
    // reached the operator, so the file had to be deleted by hand.
    status: 'delivering',
    created_at: new Date().toISOString()
  };
  // pending-draft guard: draft_id is caller-controlled on this PUBLIC
  // webhook, so an unguarded writeFileSync lets any caller rewrite a
  // draft the operator is still reviewing - the already-sent TG
  // message's Approve button would then publish the swapped text (the
  // queue payload snapshots d.text at Approve time). Semantic: an
  // existing DRAFTS/<id>.json may only be replaced when its moderation
  // is already decided AND a rewrite is expected:
  //   'rejected' - dead draft, the id is free for reuse;
  //   'rewrite'  - Handle TG Update set this when an Edit rewrite was
  //                dispatched to content-gen, which reuses draft_id -
  //                bounded to REWRITE_WINDOW_MS from rewrite_issued_at;
  //   'delivering' / 'deliver-failed' - the draft was saved but the
  //                preview sendMessage had not confirmed (or failed):
  //                no buttons ever reached the operator, so a retry
  //                under the same draft_id must get through. Keeping
  //                these rewritable is what prevents the wedge a
  //                born-'pending' file caused on delivery failure.
  // 'pending', 'approved' and any unknown/missing status refuse the
  // write (fail closed) - the caller must pick a fresh draft_id.
  // issue #70: the whole entry-read -> guard -> stamp transaction
  // runs under the per-draft state lock so an operator callback in
  // Handle TG Update serializes against this overwrite instead of
  // racing the 'moved' snapshot below. The lock body returns false
  // for every refusal (each already pushed its in-band msg - plain
  // `return`, since `continue` cannot leave an arrow fn) and true
  // only once the draft file landed; `wrote` then gates the media
  // delivery items exactly like the old `continue`s did. Media
  // resolution stays inside: it is local-FS only, bounded by the
  // 18MB cap, and moving it out would reopen the stamp gap.
  let attach = [];
  const mediaFailed = [];
  let wrote = false;
