// FNV-1a over the draft text - the same non-crypto hash family the
// preview_v tokens use (Code nodes only require fs). text_fnv pins an
// ai_check record to the exact text it was computed on, so a later
// edit is detectable by hash rather than by re-reading the body.
const pangramFnv = (s) => {
  let h = 0x811c9dc5;
  s = String(s || '');
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619) >>> 0;
  }
  return h.toString(36);
};
const pangramToday = () => new Date().toISOString().slice(0, 10);
// counter state {date, est_spent, last_seen_left, charged}: est_spent
// resets on date change (a daily window matching the credit replenish
// cycle); last_seen_left moves only when a recipe result reports the
// real 'N left' header figure. charged[] is the humanizer eval's
// per-day charge-dedupe ledger (issue #78): it MUST reset with the
// date because whichever reader rolls the counter first after
// midnight decides for both - a stale charged[tid] would let the
// eval's same-tid re-arm enqueue a real task uncharged
const pangramLoadCredits = () => {
  let c = null;
  try {
    c = JSON.parse(fs.readFileSync(PANGRAM_CREDITS, 'utf8'));
  } catch (e) {}
  if (!c || typeof c !== 'object') c = {};
  if (c.date !== pangramToday()) {
    c.date = pangramToday();
    c.est_spent = 0;
    // the per-day charge-dedupe ledger resets with the daily counter -
    // entries are only valid for same-day idempotent re-arms
    c.charged = {};
  }
  c.est_spent = Number(c.est_spent) || 0;
  if (!Number.isFinite(Number(c.last_seen_left))) {
    c.last_seen_left = null;
  }
  return c;
};
// SYNC-END: pangram-gate

// operator chat_id is pinned config: TELEGRAM_CHAT_ID env first, the
// tg.json written by sp-tg-setup as compat fallback - same resolution
// the sibling nodes use; the warn reply never learns a chat from
// task/draft content.
let chatId = ENV('TELEGRAM_CHAT_ID') || null;
if (!chatId) {
  try {
    chatId = JSON.parse(
      fs.readFileSync(STATE + '/tg.json', 'utf8')).chat_id;
  } catch (e) {}
}

const summary = { results: 0, replies: 0, notified: 0, rechecks: 0,
  stale: 0, skipped: 0, deferred: 0, notes: 0 };

// only exact 'warn' arms the path: 'off' AND 'disabled' (a
// reserved/typo value the gate prelude above rejected) both skip the
// WHOLE path - no result consumption, no replies, no re-checks, no
// stamps. The schedule trigger still ticks; this node just answers
// quietly.
if (PANGRAM_GATE !== 'warn') {
  return [{ json: { ok: true, pangram_gate: PANGRAM_GATE,
    ...summary } }];
}

// surrogate-safe truncation for the reply text, same discipline as
// the sibling cap() helpers.
const cap = (s, n) => Array.from(String(s)).slice(0, n).join('');

// WARN reply on the moderation card: reply_to_message_id anchors
// under the card's own message when draft.message_id exists; a card
// that never delivered still gets the note unthreaded - the reply
// informs, NEVER edits the card and never blocks anything.
const sendWarn = async (draft, text) => {
  if (!chatId || !token) return false;
  const body = { chat_id: chatId, text: cap(text, 300) };
  if (draft && draft.message_id) {
    body.reply_to_message_id = draft.message_id;
  }
  const r = await tg('sendMessage', body);
  return !!(r && r.ok);
};

const listDir = (d) => {
  try { return fs.readdirSync(d); } catch (e) { return null; }
};
const loadDraft = (id) => {
  try {
    return JSON.parse(
      fs.readFileSync(DRAFTS + '/' + id + '.json', 'utf8'));
  } catch (e) { return null; }
};
// idempotent consume: the processed file is renamed aside with a
// .consumed suffix instead of deleted - a re-poll can never answer
// twice on the same result, and the record of what ran survives next
// to the task file the worker moved.
const consume = (p) => {
  try { fs.renameSync(p, p + '.consumed'); } catch (e) {}
};
// 'N left' header figure the recipe read back. The recipe's 'left'
// probe can land on a trial banner ('14 days left') instead of the
// credit header - those figures must never re-sync the counter
// (last_seen_left is observability-only either way), so a 'days'
// between the digits and 'left' rejects the read.
const parseLeft = (s) => {
  const t = String(s || '');
  if (/\d+\s*days?\s*left\b/i.test(t)) return null;
  const m = /(\d+)\s*left/i.exec(t);
  return m ? Number(m[1]) : null;
};
const parseConfidence = (res) => {
  const m = /(\d{1,3})\s*%/.exec(
    String((res && (res.confidence || res.conf)) || ''));
  return m ? Number(m[1]) : null;
};
// whichever verdict probe hit; a confident 'AI Generated' outranks
// the 'possibly' labels when several probes matched (driver-side
// priority per issue #76 - the only label a future block mode could
// act on is the confident one).
const labelOf = (res) => {
  if (!res) return null;
  if (res.hit_aig || res.label === 'AI Generated') {
    return 'AI Generated';
  }
  if (res.hit_pai || res.label === 'Possibly AI') return 'Possibly AI';
  if (res.hit_ph || res.label === 'Possibly human') {
    return 'Possibly human';
  }
  return null;
};

// one queue artifact per draft: done//failed <task>.result.json carry
// the recipe's emitted probes; a bare failed/<task>.json (worker
// moved the task without writing a result) or a bare done/<task>.json
// still classify - as a failed and an inconclusive verdict
// respectively.
const processArtifact = async (dir, fname) => {
  const p = HANDS_QUEUE + '/' + dir + '/' + fname;
  const rm = /^pangram-([A-Za-z0-9_-]+)\.result\.json$/.exec(fname);
  const tm = /^pangram-([A-Za-z0-9_-]+)\.json$/.exec(fname);
  if (!rm && !tm) return;
  const draftId = (rm || tm)[1];
  const tid = 'pangram-' + draftId;
  // the worker writes <tid>.result.json BEFORE moving <tid>.json,
  // so a bare task file whose sibling result already sits in the
  // same dir is only the alphabetical-scan shadow ('x.json' sorts
  // before 'x.result.json'): the result file is the verdict
  // carrier - consume the task quietly, the sibling classifies on
  // its own pass. A missing sibling genuinely means the result
  // write failed; the bare file must still classify as today.
  if (!rm &&
      fs.existsSync(HANDS_QUEUE + '/' + dir + '/' + tid + '.result.json')) {
    consume(p);
    return;
  }
  let res = null;
  let resBad = null;
  if (rm) {
    try {
      res = JSON.parse(fs.readFileSync(p, 'utf8'));
    } catch (e) { resBad = e; }
  } else if (dir === 'done') {
    // task file in done/ with no result: the recipe ran but the
    // verdict was never recorded - honest 'inconclusive' warn
    res = { ok: true };
  }
  const draft = loadDraft(draftId);
  if (!draft) {
    // the reply has nowhere to land; the note is the whole trail,
    // and the file is still consumed exactly once
    consume(p);
    log({ draft: draftId, task: tid, action: 'ai-check-orphan-result' });
    summary.skipped++;
    return;
  }
  const pend = draft.ai_check_pending;
  if (!pend || pend.task !== tid) {
    // a rewrite dropped the pending stamp (different text) or an
    // older attempt's result outlived its stamp - either way this
    // verdict is not about the current text: consume without a
    // reply, never a second answer
    consume(p);
    log({ draft: draftId, task: tid, action: 'ai-check-stale-result' });
    summary.stale++;
    return;
  }
  // the card is still mid-delivery - no message_id anchor exists
  // yet. Defer while the pending stamp is FRESH (the card normally
  // lands seconds after the draft write); past ~10min a stuck
  // delivery must not wedge the result forever - the reply goes out
  // unthreaded instead.
  const pendAt = Date.parse(pend.at || '');
  const pendFresh = Number.isFinite(pendAt) &&
    Date.now() - pendAt < 600000;
  if (!draft.message_id && draft.status === 'delivering' &&
      pendFresh) {
    summary.deferred++;
    return;
  }
  const failed = dir === 'failed' || resBad || !res || res.ok === false;
  const label = failed ? null : labelOf(res);
  const confidence = failed ? null : parseConfidence(res);
  let errText = null;
  let line;
  if (failed) {
    // res.abort_reason is the recipe's own named abort cause (e.g.
    // 'wrong_scan_panel' - the post-click identity probe refused a
    // foreign panel): the step-level error alone would hide it, so
    // the reply quotes both, scrubbed, inside the same 120-char cap.
    const abortReason = res && res.abort_reason ?
      ' [abort_reason: ' +
      scrubSecrets(String(res.abort_reason)).slice(0, 40) + ']' : '';
    errText = cap(scrubSecrets(String(
      (res && (res.error || res.err)) ||
      (resBad && resBad.message) ||
      'recipe task failed without a result record')) + abortReason, 120);
    line = 'AI-check (Pangram): check failed - ' + errText + ' - WARN';
  } else if (label) {
    line = 'AI-check (Pangram): ' + label +
      (confidence !== null ? ' ' + confidence + '%' : '') + ' - WARN';
  } else {
    line = 'AI-check (Pangram): inconclusive - ' +
      'no verdict read back - WARN';
  }
  // claim BEFORE the reply (issue #77 review): the transition stamp
  // lands under the draft lock FIRST, while the pending stamp this
  // result answers still sits on the file - sendWarn only runs after
  // this poll provably won the claim, so two overlapping poll
  // executions can never both pass the pending check and both send.
  // The provisional record marks reply_sent 'sending'; the post-send
  // update resolves it. A veto/lock-busy means a sibling poll or a
  // rewrite owns the draft - consume once, never answer.
  const claimStatus = failed ? 'failed' : 'done';
  let stamped = null;
  try {
    stamped = withLock('draft-' + draftId, 15000, () =>
      updateDraft(draftId, (cur) => {
        const p2 = cur.ai_check_pending || {};
        const rechecks = Number((cur.ai_check &&
          cur.ai_check.rechecks) || p2.rechecks || 0);
        delete cur.ai_check_pending;
        cur.ai_check = {
          status: claimStatus,
          label: label,
          confidence: confidence,
          ...(errText !== null ? { error: errText } : {}),
          words: p2.words,
          text_fnv: p2.text_fnv,
          rechecks: rechecks,
          reply_sent: 'sending',
          at: new Date().toISOString()
        };
      }, (cur) => !!(cur && cur.ai_check_pending &&
        cur.ai_check_pending.task === tid)));
  } catch (e) {
    stamped = null;
    log({ draft: draftId, task: tid, action: 'ai-check-stamp-failed',
      error: String((e && e.message) || e).slice(0, 150) });
  }
  if (!stamped) {
    consume(p);
    log({ draft: draftId, task: tid, action: 'ai-check-stamp-vetoed' });
    return;
  }
  const sent = await sendWarn(draft, line);
  if (sent) summary.replies++;
  // resolve the provisional 'sending' marker: the send outcome is
  // stamp evidence - a TG failure after the claim is noted
  // 'warn-failed', never a throw and never a re-send (the pending
  // stamp is already consumed). A vetoed re-stamp just means the
  // draft moved on underneath us.
  try {
    withLock('draft-' + draftId, 15000, () =>
      updateDraft(draftId, (cur) => {
        cur.ai_check.reply_sent = sent === true;
        if (!sent) cur.ai_check.send_status = 'warn-failed';
        cur.ai_check.replied_at = new Date().toISOString();
      }, (cur) => !!(cur && cur.ai_check &&
        cur.ai_check.status === claimStatus &&
        cur.ai_check.reply_sent === 'sending' &&
        !cur.ai_check_pending)));
  } catch (e) {
    log({ draft: draftId, task: tid,
      action: 'ai-check-send-stamp-failed',
      error: String((e && e.message) || e).slice(0, 120) });
  }
  // counter re-sync under the shared credits lock: est_spent was
  // charged optimistically at enqueue, so only last_seen_left moves
  // here - to the recipe's own 'N left' header read-back.
  const left = parseLeft(res && res.credits_raw);
  if (left !== null) {
    try {
      withLock('pangram-credits', 15000, () => {
        const c = pangramLoadCredits();
        c.last_seen_left = left;
        writeJsonAtomic(PANGRAM_CREDITS, c);
      });
    } catch (e) {
      log({ draft: draftId, action: 'ai-check-credits-sync-failed',
        error: String((e && e.message) || e).slice(0, 120) });
    }
  }
  log({ draft: draftId, task: tid,
    action: failed ? 'ai-check-failed' : 'ai-check-done',
    label: label, confidence: confidence, words: pend.words,
    sent: sent === true });
  consume(p);
  summary.results++;
};

// result files first: consume/answer every landed check before the
// sweep arms re-checks, so a stale result never satisfies a pending
// stamp issued seconds later.
for (const dir of ['done', 'failed']) {
  const names = listDir(HANDS_QUEUE + '/' + dir);
  if (!names) continue; // missing dir: skip quietly (warn invariant)
  for (const fname of names.sort()) {
    if (fname.endsWith('.consumed')) continue;
    try {
      await processArtifact(dir, fname);
    } catch (e) {
      // per-artifact containment: one bad file must not abort the
      // sweep - warn-classified like every pangram fault
      log({ action: 'ai-check-artifact-error', file: fname,
        error: String((e && e.message) || e).slice(0, 150) });
      summary.notes++;
    }
  }
}

// draft sweep: (a) deliver the inconclusive warn once the card
// anchor exists; (b) re-arm a check: the ONE text-hash re-check
// Prepare Draft defers to here (one enqueue site per text hash) plus
// the transient-skip re-arms a settled skip stamp earned when the
// blocker cleared. Both run under the same per-draft lock the
// moderation callbacks take, and neither may throw out of the sweep.
const draftNames = listDir(DRAFTS) || [];
// skip reasons whose blockers are environmental and can clear on
// their own: the daily credit window resets, the hands-queue
// bind-mount comes back, an in-flight same-id task gets consumed, a
// transient prep-time lock-busy/io fault (enqueue_failed) clears.
// ('failed' records never appear here: they carry 'error', not
// 'reason', so no failure verdict can re-arm.) The stamp carries the
// CURRENT text_fnv, so the hash re-check below could never re-fire
// these - they re-arm explicitly instead.
const TRANSIENT_SKIP = {
  credit_cap: 1, queue_unavailable: 1, task_in_flight: 1,
  enqueue_failed: 1 };
for (const fname of draftNames.sort()) {
  const dm = /^([A-Za-z0-9_-]+)\.json$/.exec(fname);
  if (!dm) continue;
  const did = dm[1];
  const d = loadDraft(did);
  if (!d) continue;
  // pending checks are owned by the result path above
  if (d.ai_check_pending) continue;
  const ac = d.ai_check;
  if (!ac) continue;
  try {
    if (ac.status === 'inconclusive' && ac.notified !== true) {
      if (!d.message_id && d.status === 'delivering') {
        // card still mid-delivery: the reply needs its anchor, retry
        // next poll
        summary.deferred++;
        continue;
      }
      const line = 'AI-check (Pangram): inconclusive - ' +
        'text under ' + PANGRAM_MIN_WORDS + ' words (' +
        Number(ac.words || 0) + ') - WARN';
      // same claim-first discipline as processArtifact (issue #77
      // review): win the notified stamp under the draft lock BEFORE
      // sendWarn - a parallel poll sees the stamp and stays silent
      // instead of passing the un-notified check twice and sending
      // twice.
      let claimed = null;
      try {
        claimed = withLock('draft-' + did, 15000, () =>
          updateDraft(did, (cur) => {
            cur.ai_check.notified = true;
            cur.ai_check.reply_sent = 'sending';
            cur.ai_check.notified_at = new Date().toISOString();
          }, (cur) => !!(cur && cur.ai_check &&
            cur.ai_check.status === 'inconclusive' &&
            cur.ai_check.notified !== true &&
            !cur.ai_check_pending)));
      } catch (e) {
        claimed = null;
        log({ draft: did, action: 'ai-check-notify-stamp-failed',
          error: String((e && e.message) || e).slice(0, 120) });
      }
      if (!claimed) {
        // a sibling poll or a rewrite moved first - single-answer
        // stays guaranteed either way
        continue;
      }
      const sent = await sendWarn(d, line);
      if (sent) summary.replies++;
      // resolve 'sending' to the send outcome ('warn-failed' note on
      // a failed TG send) - never a throw, never a re-send
      try {
        withLock('draft-' + did, 15000, () =>
          updateDraft(did, (cur) => {
            cur.ai_check.reply_sent = sent === true;
            if (!sent) cur.ai_check.send_status = 'warn-failed';
          }, (cur) => !!(cur && cur.ai_check &&
            cur.ai_check.status === 'inconclusive' &&
            cur.ai_check.reply_sent === 'sending')));
      } catch (e) {
        log({ draft: did, action: 'ai-check-send-stamp-failed',
          error: String((e && e.message) || e).slice(0, 120) });
      }
      log({ draft: did, action: 'ai-check-inconclusive',
        words: ac.words, sent: sent === true });
      summary.notified++;
      continue;
    }

    // re-arm eligibility (issue #77 review):
    //  (a) text-hash re-check - the draft text changed under the
    //      last settled check (Edit rewrite or verbatim replace),
    //      no pending marker, budget left - ONE re-enqueue per
    //      draft (rechecks < 1), still credit-gated.
    //  (b) transient re-arm - a 'skipped' record whose reason sits in
    //      TRANSIENT_SKIP: the blocker can clear on its own, but the
    //      stamp's matching text_fnv means the hash check never
    //      re-fires it. ('failed' records can never join: their
    //      stamp carries 'error', not 'reason', so TRANSIENT_SKIP
    //      has nothing to match - the status stays terminal.) Bound
    //      once per UTC day by the rearmed_on stamp so a still-capped
    //      counter or a still-missing queue does not retry - and
    //      re-log - every 2-minute poll.
    const curFnv = pangramFnv(d.text);
    const textChanged = !!(ac.text_fnv) && ac.text_fnv !== curFnv;
    const rearm = ac.status === 'skipped' &&
      !!TRANSIENT_SKIP[ac.reason] &&
      ac.rearmed_on !== pangramToday();
    if (!(textChanged && Number(ac.rechecks || 0) < 1) && !rearm) {
      continue;
    }
    const words = pangramWords(d.text);
    if (words < PANGRAM_MIN_WORDS) continue;
    if (!fs.existsSync(HANDS_QUEUE + '/inbox')) {
      continue; // mount absent: quiet skip (warn invariant)
    }
    const cost = Math.ceil(words / 100);
    const tid = 'pangram-' + did;
    let enq = 'failed';
    let enqKind = null; // 'rearm' | 'recheck' - decided inside the lock
    try {
      enq = withLock('draft-' + did, 15000, () => {
        const dpath = DRAFTS + '/' + did + '.json';
        const cur = JSON.parse(fs.readFileSync(dpath, 'utf8'));
        // re-verify inside the lock on the CURRENT record: a pending
        // stamp landed, the text moved again, a sibling poll already
        // spent the re-check budget or armed today's re-arm, or the
        // record itself changed since the entry read
        const curAc = cur && cur.ai_check;
        const curChanged = !!(curAc && curAc.text_fnv) &&
          curAc.text_fnv !== pangramFnv(cur ? cur.text : '');
        const curRearm = !!(curAc && curAc.status === 'skipped' &&
          TRANSIENT_SKIP[curAc.reason] &&
          curAc.rearmed_on !== pangramToday());
        if (!cur || cur.ai_check_pending || !curAc ||
            (!(curChanged && Number(curAc.rechecks || 0) < 1) &&
             !curRearm)) {
          return 'vetoed';
        }
        enqKind = curRearm ? 'rearm' : 'recheck';
        // deterministic task id means a leftover artifact of the OLD
        // check (still in inbox, or landed-but-unconsumed) would let
        // a stale result satisfy the new pending stamp - defer the
        // re-check until the queue side of the old attempt is gone.
        // 'busy' is quiet and unstamped: the leftover normally clears
        // within a poll or two, so retry is cheap and log-free.
        const leftovers = [
          HANDS_QUEUE + '/inbox/' + tid + '.json',
          HANDS_QUEUE + '/done/' + tid + '.json',
          HANDS_QUEUE + '/done/' + tid + '.result.json',
          HANDS_QUEUE + '/failed/' + tid + '.json',
          HANDS_QUEUE + '/failed/' + tid + '.result.json'
        ].some((f) => fs.existsSync(f));
        if (leftovers) return 'busy';
        const outcome = withLock('pangram-credits', 15000, () => {
          const c = pangramLoadCredits();
          if (c.est_spent + cost > PANGRAM_DAILY) return 'credit_cap';
          c.est_spent += cost;
          writeJsonAtomic(PANGRAM_CREDITS, c);
          // same dot-tmp + rename the habr driver's enqueue uses:
          // the worker polls inbox/ and a torn payload must never be
          // read as a task
          const tmp = HANDS_QUEUE + '/inbox/.' + tid + '.tmp-' +
            Date.now().toString(36) +
            Math.random().toString(36).slice(2, 6);
          fs.writeFileSync(tmp, JSON.stringify({
            recipe: 'pangram_check',
            params: {
              text: String(cur.text),
              // first ~60 chars of the whitespace-collapsed text:
              // the recipe matches the newest history row whose
              // innerText starts with the checked text's head - the
              // longer the snippet, the smaller the surface a
              // substring-match click can land on by mistake
              snippet: Array.from(String(cur.text)
                .replace(/\s+/g, ' ').trim()).slice(0, 60).join('').trim()
            }
          }, null, 2));
          fs.renameSync(tmp, HANDS_QUEUE + '/inbox/' + tid + '.json');
          return 'enqueued';
        });
        // a transient re-arm is bound once per UTC day even when the
        // attempt is refused (still-capped counter): persist the
        // stamp or every poll retries + re-logs the same refusal
        if (curRearm) cur.ai_check.rearmed_on = pangramToday();
        if (outcome !== 'enqueued') {
          if (curRearm) {
            // issue #69 shape gate, same as updateDraft's: refuse to
            // persist a malformed record rather than rename it in
            validateDraftShape(cur);
            writeJsonAtomic(dpath, cur);
          }
          return outcome;
        }
        // a text-change re-enqueue spends the ONE recheck budget; a
        // transient re-arm on UNCHANGED text does not - the budget
        // stays reserved for an actual rewrite
        if (curChanged) {
          cur.ai_check.rechecks = Number(cur.ai_check.rechecks || 0) + 1;
        }
        cur.ai_check_pending = { task: tid,
          text_fnv: pangramFnv(cur.text), words: words, cost: cost,
          at: new Date().toISOString() };
        // issue #69 shape gate before the rename, same discipline
        // as updateDraft's embedded validateDraftShape call
        validateDraftShape(cur);
        writeJsonAtomic(dpath, cur);
        return 'enqueued';
      });
    } catch (e) {
      enq = 'failed';
      log({ draft: did, action: 'ai-check-recheck-failed',
        error: String((e && e.message) || e).slice(0, 150) });
    }
    if (enq === 'enqueued') {
      log({ draft: did, task: tid,
        action: enqKind === 'rearm' ? 'ai-check-rearm' :
          'ai-check-recheck',
        words: words, cost: cost });
      summary.rechecks++;
    } else if (enq === 'credit_cap') {
      log({ draft: did,
        action: enqKind === 'rearm' ? 'ai-check-rearm-credit-cap' :
          'ai-check-recheck-credit-cap',
        words: words, cost: cost });
      summary.notes++;
    }
  } catch (e) {
    // per-draft containment: one malformed draft file must not abort
    // the sweep
    log({ draft: did, action: 'ai-check-sweep-error',
      error: String((e && e.message) || e).slice(0, 150) });
    summary.notes++;
  }
}

return [{ json: { ok: true, pangram_gate: PANGRAM_GATE, ...summary } }];
